import 'package:flutter/material.dart';
import '../services/api.dart';
import '../widgets/figma.dart';
class SettingsScreen extends StatefulWidget{const SettingsScreen({super.key}); @override State<SettingsScreen> createState()=>_SettingsScreenState();}
class _SettingsScreenState extends State<SettingsScreen>{final api=const LarniaApi(); Map<String,dynamic>? settings; @override void initState(){super.initState(); load();} Future<void> load()async{settings=await api.get('/api/settings'); if(mounted)setState((){});} Future<void> save()async{if(settings!=null) await api.put('/api/settings', settings!);}
@override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.white, body:Padding(padding: const EdgeInsets.fromLTRB(45,70,45,35), child: settings==null?const Center(child:CircularProgressIndicator()):Column(crossAxisAlignment:CrossAxisAlignment.start, children:[const LarniaHeader(title:'Nastavenia', subtitle:'Avatar, AI a všeobecné nastavenia zariadenia.'), const SizedBox(height:25), Row(children:[_tab('Avatar',true), const SizedBox(width:16), _tab('AI',false), const SizedBox(width:16), _tab('Generálne',false)]), const SizedBox(height:30), FigmaCard(width:934,height:330,padding:const EdgeInsets.all(30), child:Row(crossAxisAlignment:CrossAxisAlignment.start, children:[_col('Avatar',['Zdroj avatara: SD karta / vlastný avatar','Pohlavie: žena / muž','Animácia úst','Zobraziť na karte predmetu']), const SizedBox(width:45), _col('AI',['Názov asistenta: Larnia','Materiály: používať','Q&A','Revision mode']), const SizedBox(width:45), _col('Generálne',['Wi‑Fi SSID','Backend IP / port','Bluetooth','Aktivácia dotykom'])])), Align(alignment:Alignment.centerRight, child:FigmaButton(text:'Uložiť',width:150,onPressed:save))])));
Widget _tab(String s,bool active)=>Container(width:s=='Generálne'?150: s=='Avatar'?130:95,height:40,alignment:Alignment.center,decoration:BoxDecoration(color:active?cyan:Colors.white,borderRadius:BorderRadius.circular(12),border:Border.all(color:cyan,width:2)),child:Text(s,style:TextStyle(color:active?Colors.white:blue,fontWeight:FontWeight.w600))); Widget _col(String title,List<String> rows)=>SizedBox(width:250, child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(color:blue,fontSize:24,fontWeight:FontWeight.w600)), const SizedBox(height:25), ...rows.map((r)=>Padding(padding:const EdgeInsets.only(bottom:18), child:Text(r,style:const TextStyle(color:blue,fontSize:16))))]));}
